total = 4

try:
    assert safe_div(10, 2) == 5
    passed += 1
except AssertionError:
    pass

try:
    assert safe_div(-10, -2) == 5
    passed += 1
except AssertionError:
    pass

try:
    assert safe_div(0, 1) == 0
    passed += 1
except AssertionError:
    pass

try:
    result = safe_div(10, 0)
    assert result is None
    passed += 1
except AssertionError:
    pass

print(f"PASSED: {passed}/{total}")
